Ersetzt src/main.rs. Die wichtigsten Bausteine: #[derive(Serialize, Deserialize)] – erzeugt automatisch den Code zum Umwandeln in und aus JSON Handler – gewöhnliche async fn. Was sie brauchen, geben sie als Parameter an: Query liest Werte aus der Adresse, Json aus dem mitgeschickten Inhalt, State greift auf gemeinsame Daten zu. Arc<Mutex<…>> – eine Liste, die sich alle gleichzeitig laufenden Anfragen sicher teilen können Router – legt zentral fest, welcher Handler welche Adresse und Methode beantwortet TcpListener::bind("127.0.0.1:3000") – der Server ist nur vom eigenen Rechner aus erreichbar, auf Port 3000 nano src/main.rs Die Datei hat schon Inhalt aus der Vorlage, der vollständig ersetzt wird. Lösche ihn zuerst: Alt+\ springt an den Anfang, Alt+A beginnt eine Markierung, Alt+/ springt ans Ende, Strg+K schneidet alles Markierte aus. Füge diesen Inhalt ein (im Terminal mit Strg+Umschalt+V), speichere mit Strg+O und Enter und beende nano mit Strg+X: use std::sync::{Arc, Mutex}; use axum::{ extract::{Query, State}, http::StatusCode, routing::get, Json, Router,
};
use serde::{Deserialize, Serialize}; // Datentypen: Serialize/Deserialize wandeln automatisch in JSON um und zurück
#[derive(Clone, Serialize)]
struct Notiz { id: usize, titel: String,
} #[derive(Deserialize)]
struct NeueNotiz { titel: String,
} #[derive(Deserialize)]
struct Name { name: Option<String>,
} // Gemeinsamer Zustand: die Notizliste, sicher für gleichzeitige Zugriffe
type Notizen = Arc<Mutex<Vec<Notiz>>>; // GET /hallo?name=... liefert eine Begrüßung als JSON
async fn hallo(Query(abfrage): Query<Name>) -> Json<serde_json::Value> { let name = abfrage.name.unwrap_or_else(|| "Welt".to_string()); Json(serde_json::json!({ "gruss": format!("Hallo {name}!") }))
} // GET /notizen liefert alle Notizen
async fn liste(State(notizen): State<Notizen>) -> Json<Vec<Notiz>> { Json(notizen.lock().unwrap().clone())
} // POST /notizen legt eine Notiz an; der Inhalt kommt als JSON
async fn anlegen( State(notizen): State<Notizen>, Json(eingabe): Json<NeueNotiz>,
) -> (StatusCode, Json<Notiz>) { let mut liste = notizen.lock().unwrap(); let notiz = Notiz { id: liste.len() + 1, titel: eingabe.titel }; liste.push(notiz.clone()); (StatusCode::CREATED, Json(notiz))
} #[tokio::main]
async fn main() { let notizen: Notizen = Arc::new(Mutex::new(Vec::new())); // Router: welche Funktion beantwortet welche Adresse und Methode let app = Router::new() .route("/hallo", get(hallo)) .route("/notizen", get(liste).post(anlegen)) .with_state(notizen); // Nur vom eigenen Rechner aus erreichbar, Port 3000 let listener = tokio::net::TcpListener::bind("127.0.0.1:3000").await.unwrap(); println!("Axum läuft auf http://127.0.0.1:3000"); axum::serve(listener, app).await.unwrap();
}

