519.body:
osm2pgsql arbeitet hier mit der Flex -Ausgabe: Ein Lua-Skript legt die Tabellen fest und entscheidet für jedes Objekt, wohin es gehört. Das Beispiel legt vier Tabellen an: strassen (Wege und Straßen als Linien), gebaeude (Umrisse), flaechen (Wald, Wasser, Wiesen, Parks usw.) und orte (Punkte wie Geschäfte, Ärzte, Schulen). Die Geometrien speichert osm2pgsql automatisch in Web-Mercator (EPSG:3857), der Projektion der Webkarten. Martin muss dann nichts umrechnen. sudo nano /srv/osm/martin/ahrensburg.lua Füge diesen Inhalt ein (im Terminal mit Strg+Umschalt+V), speichere mit Strg+O und Enter und beende nano mit Strg+X: -- Importregeln für Martin: vier einfache Tabellen in Web-Mercator (EPSG:3857) local strassen = osm2pgsql.define_way_table('strassen', { { column = 'art', type = 'text' }, { column = 'name', type = 'text' }, { column = 'geom', type = 'linestring', not_null = true },
}) local gebaeude = osm2pgsql.define_area_table('gebaeude', { { column = 'art', type = 'text' }, { column = 'hausnummer', type = 'text' }, { column = 'geom', type = 'geometry', not_null = true },
}) local flaechen = osm2pgsql.define_area_table('flaechen', { { column = 'art', type = 'text' }, { column = 'name', type = 'text' }, { column = 'geom', type = 'geometry', not_null = true },
}) local orte = osm2pgsql.define_node_table('orte', { { column = 'art', type = 'text' }, { column = 'name', type = 'text' }, { column = 'geom', type = 'point', not_null = true },
}) -- Welche Schlüssel eine Fläche beschreiben (in dieser Reihenfolge geprüft)
local flaechen_schluessel = { 'natural', 'landuse', 'leisure', 'water' } local function flaechen_art(tags) for _, schluessel in ipairs(flaechen_schluessel) do if tags[schluessel] then return schluessel .. '=' .. tags[schluessel] end end return nil
end function osm2pgsql.process_node(object) local art = object.tags.amenity or object.tags.shop or object.tags.place if art then orte:insert({ art = art, name = object.tags.name, geom = object:as_point(), }) end
end function osm2pgsql.process_way(object) local tags = object.tags if tags.building and object.is_closed then gebaeude:insert({ art = tags.building, hausnummer = tags['addr:housenumber'], geom = object:as_polygon(), }) elseif tags.highway then strassen:insert({ art = tags.highway, name = tags.name, geom = object:as_linestring(), }) elseif object.is_closed then local art = flaechen_art(tags) if art then flaechen:insert({ art = art, name = tags.name, geom = object:as_polygon(), }) end end
end function osm2pgsql.process_relation(object) local tags = object.tags if tags.type ~= 'multipolygon' then return end if tags.building then gebaeude:insert({ art = tags.building, hausnummer = tags['addr:housenumber'], geom = object:as_multipolygon(), }) return end local art = flaechen_art(tags) if art then flaechen:insert({ art = art, name = tags.name, geom = object:as_multipolygon(), }) end
end Bei Flächen steht in der Spalte art Schlüssel und Wert zusammen, z. B. natural=water oder landuse=forest. Danach richtet die Testseite in Schritt 22 die Farben aus.

